  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة مما يلي:', '["ذات", "نفس", "كيان", "الاقتداء"]'::jsonb, 3, 'الذات والنفس والكيان ألفاظ مترادفة تدل على حقيقة الشيء، أما الاقتداء فمعناه اتباع الغير.', NULL, 'ad240826-2026-4c00-9d00-240820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما أهم الصفات التي يجب أن يتصف بها المسعف؟', '["السرعة البديهية في اتخاذ القرار", "القوة البدنية العالية", "معرفة أسماء الأدوية كاملة", "تهدئة المصاب فقط"]'::jsonb, 0, 'النص ينص على أن أهم صفات المسعف سرعته في التعامل الجيد مع الحالة واتخاذ القرار المناسب في وقته.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82401-2026-4c00-9d00-000000000001', 'يتوقف على طريقة تعامل المسعف مع المصاب الكثير من العوامل، ومن أهم الصفات التي يجب أن يتصف بها المسعف سرعته في التعامل الجيد مع الحالة واتخاذ القرار المناسب في التوقيت المناسب.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما معنى كلمة (عصب) الواردة في الفقرة الثانية؟', '["محور", "أغلبية", "عصابة", "منشأ"]'::jsonb, 0, 'عصب الاقتصاد أي محوره الذي يقوم عليه؛ فالزراعة هي قوام الاقتصاد الكيني.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82402-2026-4c00-9d00-000000000002', '١- تقع جمهورية كينيا في القسم الشرقي من القارة الأفريقية، وحدودها مرتبطة مع كثير من الدول الأفريقية؛ فالمحيط الهندي يحدها من الجهة الشرقية، وأوغندا من الجهة الغربية، وتنزانيا من الجهة الجنوبية، وأثيوبيا والسودان من الجهة الشمالية، أما من الجهة الشمالية الشرقية فتحدها الصومال.
٢- وتنقسم أراضيها إلى قسمين: ساحلية ومرتفعة، ويعيش سكانها ضمن ٨٪ من مساحتها فقط، والباقي واحات ومساحات شاسعة تعيش فيها حيوانات نادرة. فالمنطقة الساحلية شريط ضيق لكن تربته خصبة في معظم أجزائها خاصة في الجنوب، ويعيش نحو ٧٥٪ من سكان كينيا في الأراضي المرتفعة وتقع فيها نيروبي أكبر مدينة في كينيا، ويعمل أغلب سكانها في الزراعة التي تعد عصب الاقتصاد الكيني، ويتكلم أكثر السكان اللغة الساحلية إلا أن المتعلمين منهم يتحدثون الإنجليزية وهي اللغة المعتمدة في البلاد.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', '(إلا أن) الواردة في الفقرة الثانية يمكن استبدالها بـ:', '["غير أن", "حيث أن", "مع أن", "رغم أن"]'::jsonb, 0, '«إلا أن» أداة استدراك، وأقرب البدائل أداء لهذا المعنى في الموضع نفسه هي «غير أن».', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82402-2026-4c00-9d00-000000000002', '١- تقع جمهورية كينيا في القسم الشرقي من القارة الأفريقية، وحدودها مرتبطة مع كثير من الدول الأفريقية؛ فالمحيط الهندي يحدها من الجهة الشرقية، وأوغندا من الجهة الغربية، وتنزانيا من الجهة الجنوبية، وأثيوبيا والسودان من الجهة الشمالية، أما من الجهة الشمالية الشرقية فتحدها الصومال.
٢- وتنقسم أراضيها إلى قسمين: ساحلية ومرتفعة، ويعيش سكانها ضمن ٨٪ من مساحتها فقط، والباقي واحات ومساحات شاسعة تعيش فيها حيوانات نادرة. فالمنطقة الساحلية شريط ضيق لكن تربته خصبة في معظم أجزائها خاصة في الجنوب، ويعيش نحو ٧٥٪ من سكان كينيا في الأراضي المرتفعة وتقع فيها نيروبي أكبر مدينة في كينيا، ويعمل أغلب سكانها في الزراعة التي تعد عصب الاقتصاد الكيني، ويتكلم أكثر السكان اللغة الساحلية إلا أن المتعلمين منهم يتحدثون الإنجليزية وهي اللغة المعتمدة في البلاد.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أي الآتي صحيح حسب الفقرة الثانية؟', '["أغلب النشاط الزراعي في الأراضي المرتفعة", "٧٥٪ من سكان كينيا يعملون في الزراعة", "التربة الخصبة لا تتوفر إلا في المناطق المرتفعة", "ربع مساحة كينيا صالح للزراعة"]'::jsonb, 0, 'النص يذكر أن أغلب سكان المرتفعات يعملون بالزراعة وأنها عصب الاقتصاد، فأغلب النشاط الزراعي هناك. أما نسبة ٧٥٪ فهي نسبة من يسكنون المرتفعات، وأغلبهم لا كلهم يعملون بالزراعة.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82402-2026-4c00-9d00-000000000002', '١- تقع جمهورية كينيا في القسم الشرقي من القارة الأفريقية، وحدودها مرتبطة مع كثير من الدول الأفريقية؛ فالمحيط الهندي يحدها من الجهة الشرقية، وأوغندا من الجهة الغربية، وتنزانيا من الجهة الجنوبية، وأثيوبيا والسودان من الجهة الشمالية، أما من الجهة الشمالية الشرقية فتحدها الصومال.
٢- وتنقسم أراضيها إلى قسمين: ساحلية ومرتفعة، ويعيش سكانها ضمن ٨٪ من مساحتها فقط، والباقي واحات ومساحات شاسعة تعيش فيها حيوانات نادرة. فالمنطقة الساحلية شريط ضيق لكن تربته خصبة في معظم أجزائها خاصة في الجنوب، ويعيش نحو ٧٥٪ من سكان كينيا في الأراضي المرتفعة وتقع فيها نيروبي أكبر مدينة في كينيا، ويعمل أغلب سكانها في الزراعة التي تعد عصب الاقتصاد الكيني، ويتكلم أكثر السكان اللغة الساحلية إلا أن المتعلمين منهم يتحدثون الإنجليزية وهي اللغة المعتمدة في البلاد.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يستفاد من الفقرة الثانية أن:', '["المناطق الساحلية لا تحتوي على تربة خصبة", "كل الكينيين يتحدثون اللغة الساحلية", "المتعلمين يتحدثون اللغة الإنجليزية", "الكينيين يزرعون الشاي"]'::jsonb, 2, 'النص صريح: أكثر السكان يتكلمون الساحلية إلا أن المتعلمين يتحدثون الإنجليزية وهي اللغة المعتمدة.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82402-2026-4c00-9d00-000000000002', '١- تقع جمهورية كينيا في القسم الشرقي من القارة الأفريقية، وحدودها مرتبطة مع كثير من الدول الأفريقية؛ فالمحيط الهندي يحدها من الجهة الشرقية، وأوغندا من الجهة الغربية، وتنزانيا من الجهة الجنوبية، وأثيوبيا والسودان من الجهة الشمالية، أما من الجهة الشمالية الشرقية فتحدها الصومال.
