  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'تقع كينيا في:', '["شمال أفريقيا غرب المحيط الهندي", "شمال أفريقيا شرق المحيط الهندي", "جنوب أفريقيا", "شرق أفريقيا غرب المحيط الهندي"]'::jsonb, 3, 'كينيا في القسم الشرقي من أفريقيا، والمحيط الهندي يحدها من الشرق أي أنها تقع غربه.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82402-2026-4c00-9d00-000000000002', '١- تقع جمهورية كينيا في القسم الشرقي من القارة الأفريقية، وحدودها مرتبطة مع كثير من الدول الأفريقية؛ فالمحيط الهندي يحدها من الجهة الشرقية، وأوغندا من الجهة الغربية، وتنزانيا من الجهة الجنوبية، وأثيوبيا والسودان من الجهة الشمالية، أما من الجهة الشمالية الشرقية فتحدها الصومال.
