  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يمكن استبدال حرف (من) في النص بـ:', '["عن", "حتى", "إلى", "على"]'::jsonb, 0, 'المعنى: تمحي الحياء عن وجهه؛ فحرف الجر «عن» يؤدي المعنى نفسه في هذا الموضع.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82403-2026-4c00-9d00-000000000003', 'كثرة سؤال الرجل للناس تمحي الحياء من وجهه.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'المقصود بـ(السؤال) في سياق النص:', '["العلم", "المال", "العطاء", "الكرم"]'::jsonb, 1, 'سؤال الناس هنا هو طلب المال والحاجات منهم، وهو الذي يذهب ماء الوجه مع كثرته.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82403-2026-4c00-9d00-000000000003', 'كثرة سؤال الرجل للناس تمحي الحياء من وجهه.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'النص يحث على:', '["الحياء", "التعفف", "الكرم", "الصبر"]'::jsonb, 1, 'إذا كانت كثرة السؤال تمحي الحياء فالنص يدعو إلى تركها، أي إلى التعفف عما في أيدي الناس.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82403-2026-4c00-9d00-000000000003', 'كثرة سؤال الرجل للناس تمحي الحياء من وجهه.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'النوع الأول من داء السكري — كما يُفهم من القطعة — هو الذي يعتمد على:', '["الأنسولين", "الدهون", "السكر", "الرياضة"]'::jsonb, 0, 'وصف النص النوع الثاني بأنه غير المعتمد على الأنسولين، فيلزم أن النوع الأول هو المعتمد عليه.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يُفهم من النص أن إصابات السكري عند الأطفال في:', '["تنامٍ", "تراجع", "ثبات", "اختفاء"]'::jsonb, 0, 'النص يذكر أن النوع الثاني بين الأطفال بلغ عشرة أضعاف ما كان عليه قبل عقد، وهذا تنامٍ واضح.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'معنى كلمة (وبائي) في سياق النص:', '["معدٍ", "خطر", "قاتل", "منتشر"]'::jsonb, 3, 'وصف المرض بالوبائي هنا إشارة إلى سعة انتشاره في المجتمع، لا إلى العدوى بمعناها الطبي.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'علاقة (داء السكري) بـ(زيادة الوزن عند الأطفال):', '["طردية", "عكسية", "تزامنية", "تماثلية"]'::jsonb, 0, 'النص يربط السكري بالدهون والخمول؛ فكلما زاد الوزن زاد احتمال الإصابة، وهذه علاقة طردية.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الفقرة الأخيرة تدل على:', '["النصح", "التعجب", "الاستفهام", "المدح"]'::jsonb, 0, 'الفقرة تحذر من الاعتماد على الرفاهية والخمول وما يقود إليه من مرض، وهذا أسلوب نصح وتحذير.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 5, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما الذي ينصح به الأطباء في النص لتجنب الإصابة بالسكري؟', '["ترك السكر", "تقليل الدهون", "ممارسة الرياضة", "حماية الجسم"]'::jsonb, 1, 'النصيحة المنسوبة للأطباء نصًّا هي تقليل الدهون والتخلص من المشبعة والمهدرجة. أما النشاط البدني فورد كحقيقة عامة لا كنصيحة الأطباء.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 6, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'علاقة (النشاط البدني) بـ(احتمال الإصابة بمرض السكري):', '["طردية", "عكسية", "نتيجة", "تزامنية"]'::jsonb, 1, 'النص يقرر أن النشاط البدني يقلل احتمالية الإصابة؛ فكلما زاد أحدهما نقص الآخر، وهذه علاقة عكسية.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 7, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
