  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أي الآتي صحيح من خلال النص؟', '["اعتمد المجتمع بإفراط على الرفاهية", "ترك المجتمع التعامل مع الرفاهية", "انخفضت إصابات الأطفال بالسكري", "النوع الثاني يعتمد على الأنسولين"]'::jsonb, 0, 'النص يقول إن المجتمع أصبح يعتمد على الرفاهية والخمول حتى ظهر المرض، وهذا هو الإفراط المقصود.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 9, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'علاقة (النشاطات البدنية) بـ(الصحة):', '["طردية", "عكسية", "متذبذبة", "لا علاقة بينهما"]'::jsonb, 0, 'النشاط البدني يقلل احتمال المرض أي يرفع مستوى الصحة؛ فالعلاقة بينه وبين الصحة طردية، بعكس علاقته باحتمال الإصابة.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 10, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'من خلال القطعة نفهم أنه لا بد من:', '["المبالغة في استخدام التقنية", "الحرص على استخدام التقنية", "التقليل من استخدام التقنية", "منع التقنية نهائيًا"]'::jsonb, 2, 'الرفاهية والخمول اللذان حذر منهما النص من أبرز أسبابهما الإفراط في وسائل التقنية، فالمطلوب التقليل منها لا منعها.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82404-2026-4c00-9d00-000000000004', 'أوضح الباحثون أن النوع الثاني من داء السكري — وهو غير المعتمد على الأنسولين — يحدث بين الأطفال، وقد بلغ عشرة أضعاف ما كان عليه منذ عقد من الزمن، وينصح الأطباء بتقليل الدهون أو التخلص من الدهون المشبعة والدهون المهدرجة. النشاط البدني يقلل من احتمالية الإصابة بمرض السكري؛ فكلما زاد خمول الإنسان زادت نسبة احتمالية إصابته بالسكري. أصبح المجتمع في عصرنا الحالي يعتمد على الرفاهية والخمول مما أدى إلى ظهور مرض السكري، وهو مرض وبائي في المجتمع.', 11, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أنسب عنوان للنص:', '["كتم الأسرار", "فضيلة الطيبة", "عدم الثقة بالآخرين", "ترجمة السلوك إلى أفعال"]'::jsonb, 1, 'النص كله يدور حول الطيبة: كن طيبًا، وأخفِ طيبتك، والتمسها في الناس؛ فأنسب عنوان: فضيلة الطيبة.', NULL, 'ad240826-2026-4c00-9d00-240820260001', 'e1a82405-2026-4c00-9d00-000000000005', 'كن طيبًا، واحرص على ألا يعرف أحد أنك طيب لئلا يعتريك العجب، وابحث عن الجانب الطيب في كل من تعامله من الناس، وإياك أن تفتش عن الجانب السيئ فيهم، وقل الحق دائمًا ولا سيما على نفسك.', 1, 'active', false);
END IF;
