-- تحقق نهائي
DO $chk$
DECLARE n INT; nq INT; nv INT; np INT;
BEGIN
  SELECT COUNT(*) INTO n FROM questions WHERE leak_group_id = 'ad240826-2026-4c00-9d00-240820260001';
  SELECT COUNT(*) INTO nq FROM questions WHERE leak_group_id = 'ad240826-2026-4c00-9d00-240820260001' AND section = 'quant';
  SELECT COUNT(*) INTO nv FROM questions WHERE leak_group_id = 'ad240826-2026-4c00-9d00-240820260001' AND section = 'verbal';
  SELECT COUNT(*) INTO np FROM questions WHERE leak_group_id = 'ad240826-2026-4c00-9d00-240820260001' AND passage_id IS NOT NULL;
  RAISE NOTICE 'إجمالي: % — كمي: % — لفظي: % — قطع: %', n, nq, nv, np;
  IF n <> 77 THEN RAISE EXCEPTION 'عدد الأسئلة % لا يطابق المتوقع 77', n; END IF;
  IF nq <> 26 OR nv <> 51 THEN RAISE EXCEPTION 'توزيع كمي/لفظي غير مطابق'; END IF;
